typedef struct { int q; } blk;


void quant_a(const float *x, blk *y) { y->q = (int)(x[0] * 2.0f); }


template <typename idx_t, typename block_type, int qk, void (*quantize_func)(const float *, block_type *)>
void k_rows(const float *src, block_type *dst, int n) {
  int i = __nfcxx_ctaid_x() * __nfcxx_ntid_x() + __nfcxx_tid_x();
  if (i < n) quantize_func(src + i * qk, dst + i);
}
extern "C" void __nfcxx_k_k_rows_int_blk_1_quant_a(const float *src, blk *dst, int n) { k_rows<int, blk, 1, quant_a>(src, dst, n); }
